package controller
import("errors";"net/http";"github.com/gin-gonic/gin";"github.com/google/uuid";"github.com/onoja217/users-management-app/internal/audit";"github.com/onoja217/users-management-app/internal/httpx";"github.com/onoja217/users-management-app/internal/models";"github.com/onoja217/users-management-app/internal/service")
type AssessmentResultController struct{service *service.AssessmentResultService}
func NewAssessmentResultController(s *service.AssessmentResultService)*AssessmentResultController{return &AssessmentResultController{s}}
type resultRequest struct{AssessmentID uuid.UUID `json:"assessment_id" binding:"required"`;EnrollmentID uuid.UUID `json:"enrollment_id" binding:"required"`;Score float64 `json:"score" binding:"required"`;Comment string `json:"comment" binding:"max=500"`}
func resultError(c *gin.Context,e error){switch{case errors.Is(e,service.ErrResultNotFound):httpx.Error(c,404,"result_not_found","assessment result not found");case errors.Is(e,service.ErrResultDuplicate):httpx.Error(c,409,"result_duplicate","result already exists");case errors.Is(e,service.ErrResultInvalid):httpx.Error(c,400,"invalid_result","invalid assessment result");default:httpx.Error(c,500,"result_operation_failed","result operation failed")}}
func(ctrl *AssessmentResultController)List(c *gin.Context){v,e:=ctrl.service.List();if e!=nil{resultError(c,e);return};c.JSON(200,v)}
func(ctrl *AssessmentResultController)Get(c *gin.Context){id,e:=uuid.Parse(c.Param("id"));if e!=nil{httpx.Error(c,400,"invalid_result_id","invalid result id");return};v,e:=ctrl.service.Get(id);if e!=nil{resultError(c,e);return};c.JSON(200,v)}
func(ctrl *AssessmentResultController)Create(c *gin.Context){var r resultRequest;if e:=c.ShouldBindJSON(&r);e!=nil{httpx.Validation(c,httpx.ValidationErrors(e));return};v,e:=ctrl.service.Create(models.AssessmentResult{AssessmentID:r.AssessmentID,EnrollmentID:r.EnrollmentID,Score:r.Score,Comment:r.Comment});if e!=nil{resultError(c,e);return};actor,_:=uuid.Parse(c.GetString("user_id"));_=audit.Record(ctrl.service.DB(),c,&actor,"assessment_result.create","assessment_result",&v.ID,nil);c.JSON(http.StatusCreated,v)}
func(ctrl *AssessmentResultController)Update(c *gin.Context){id,e:=uuid.Parse(c.Param("id"));if e!=nil{httpx.Error(c,400,"invalid_result_id","invalid result id");return};var r resultRequest;if e=c.ShouldBindJSON(&r);e!=nil{httpx.Validation(c,httpx.ValidationErrors(e));return};v:=models.AssessmentResult{ID:id,AssessmentID:r.AssessmentID,EnrollmentID:r.EnrollmentID,Score:r.Score,Comment:r.Comment};if e=ctrl.service.Update(v);e!=nil{resultError(c,e);return};actor,_:=uuid.Parse(c.GetString("user_id"));_=audit.Record(ctrl.service.DB(),c,&actor,"assessment_result.update","assessment_result",&v.ID,nil);c.JSON(200,v)}
func(ctrl *AssessmentResultController)Delete(c *gin.Context){id,e:=uuid.Parse(c.Param("id"));if e!=nil{httpx.Error(c,400,"invalid_result_id","invalid result id");return};if e=ctrl.service.Delete(id);e!=nil{resultError(c,e);return};actor,_:=uuid.Parse(c.GetString("user_id"));_=audit.Record(ctrl.service.DB(),c,&actor,"assessment_result.delete","assessment_result",&id,nil);c.JSON(200,gin.H{"message":"assessment result deleted"})}
func(ctrl *AssessmentResultController)ReportCard(c *gin.Context){eid,e:=uuid.Parse(c.Param("enrollmentId"));if e!=nil{httpx.Error(c,400,"invalid_enrollment_id","invalid enrollment id");return};tid,e:=uuid.Parse(c.Param("termId"));if e!=nil{httpx.Error(c,400,"invalid_term_id","invalid term id");return};v,e:=ctrl.service.ReportCard(eid,tid);if e!=nil{resultError(c,e);return};c.JSON(200,v)}